INSERT INTO auth.users (id) VALUES
    ('00000000-0000-4000-8000-000000000001'),
    ('00000000-0000-4000-8000-000000000002');

CREATE TABLE public.restore_records (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id uuid NOT NULL REFERENCES auth.users (id),
    label text NOT NULL UNIQUE,
    score int NOT NULL CHECK (score >= 0)
);
ALTER TABLE public.restore_records OWNER TO recovery_owner;
CREATE INDEX restore_records_user_score ON public.restore_records (user_id, score DESC);
ALTER TABLE public.restore_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_records ON public.restore_records
    FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
REVOKE ALL ON public.restore_records FROM PUBLIC;
GRANT SELECT ON public.restore_records TO authenticated;
ALTER DEFAULT PRIVILEGES FOR ROLE recovery_owner IN SCHEMA public
    GRANT SELECT ON TABLES TO authenticated;

CREATE FUNCTION public.restore_digest(label text) RETURNS text
LANGUAGE sql IMMUTABLE SECURITY INVOKER
RETURN encode(extensions.digest(label, 'sha256'), 'hex');
ALTER FUNCTION public.restore_digest(text) OWNER TO recovery_owner;
REVOKE EXECUTE ON FUNCTION public.restore_digest(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.restore_digest(text) TO authenticated;

